insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (1, 1, 0, 1, true, 'Introduction to AI Testing', 'What is AI testing, why it matters, and how it differs from traditional software testing. Covers LLMs, non-determinism, evaluation strategies, and the modern AI testing landscape.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-1/slide1?lang=en');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (2, 1, 1, 2, true, 'Prompt Engineering for Testers', 'How to write prompts that produce consistent, testable outputs. Covers prompt structure, system messages, temperature, and prompt injection basics.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-2/slide1?lang=en');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (3, 1, 2, 3, true, 'Testing LLM Outputs', 'Evaluation frameworks for LLM responses — semantic similarity, factuality checks, toxicity detection, and JSON schema validation.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-3/slide1?lang=en');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (4, 1, 3, 4, true, 'Playwright for AI Applications', 'End-to-end testing of AI-powered UIs with Playwright — handling dynamic content, testing streaming responses, and building resilient selectors.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-4/slide1?lang=en');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (5, 1, 4, 5, true, 'API Testing with AI Features', 'Testing AI APIs with pytest and Requests — mocking LLM responses, testing edge cases, and validating structured outputs.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-5/slide1?lang=en');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (6, 1, 5, 6, true, 'CI/CD for AI Test Suites', 'Running AI tests in GitHub Actions — parallelism, flakiness handling, cost management, and integrating LLM-as-judge into pipelines.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-6/slide1?lang=en');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (7, 1, 6, 7, true, 'Security Testing for AI', 'Prompt injection attacks, data leakage, jailbreaking, and adversarial testing. How to write security tests for LLM-powered features.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-7/slide1?lang=en');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (8, 1, 7, 8, true, 'Performance Testing AI Features', 'Latency benchmarking, throughput testing, and token-cost optimization. Load testing AI endpoints and establishing performance baselines.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-8/slide1?lang=en');